"""Generate copy-only host installers from the packaged portable producer."""
from __future__ import annotations

import json
import shlex
from string import Template

from ..install.agent_skills_projection import MANIFEST_NAME, agent_skills_manifest
from .host_adapters import HOST_ADAPTERS, checksum_inventory, host_adapter_manifest


_SH = Template(r'''#!/bin/sh
# Generated by omj docs agent-skills; edit the catalog/producer, not this file.
# Source inventory SHA256: @OMJ_DIGEST@
set -eu
fail() { printf '%s\n' "$*" >&2; exit 1; }
scope=repo
case $# in
    0) ;;
    1) [ "$1" = --user ] || fail 'Usage: install.sh [--user]'; scope=user ;;
    *) fail 'Usage: install.sh [--user]' ;;
esac
base=$(pwd -P)
if [ "$scope" = user ]; then
    [ -n "${HOME:-}" ] || fail 'HOME is required for --user'
    base=$(CDPATH= cd -- "$HOME" && pwd -P)
    target="$base/@OMJ_USER_PATH@"
else
    target="$base/@OMJ_REPO_PATH@"
fi
source=$(dirname -- "$0")/../@OMJ_SOURCE_SH@
[ ! -L "$source" ] || fail 'Symlink source root'
source=$(CDPATH= cd -- "$source" && pwd -P)
if command -v sha256sum >/dev/null 2>&1; then
    checksum() { sha256sum "$@"; }
elif command -v shasum >/dev/null 2>&1; then
    checksum() { shasum -a 256 "$@"; }
else
    fail 'SHA256 verification requires sha256sum or shasum'
fi
checksums=$(cat <<'OMJ_CHECKSUMS'
@OMJ_CHECKSUMS@
OMJ_CHECKSUMS
)
paths=$(cat <<'OMJ_PATHS'
@OMJ_PATHS@
OMJ_PATHS
)
[ -z "$(find "$source" ! -type f ! -type d -print)" ] || fail 'Unsupported source entry (including symlink)'
actual=$(cd "$source" && find . -type f -print | LC_ALL=C sort)
expected=$(printf '%s\n' "$paths" | while IFS= read -r path; do printf './%s\n' "$path"; done)
[ "$actual" = "$expected" ] || fail 'Source file inventory mismatch'
verify() { printf '%s\n' "$checksums" | (cd "$1" && checksum -c -) >/dev/null || fail 'Skill digest mismatch'; }
verify "$source"
# No destination path component (leaf or ancestor, up to $base) may be a
# symlink. Reused at preflight and again immediately before each write
# below: a same-UID attacker who plants a link after preflight is still
# caught at the latest possible instant before that path is touched. This
# narrows, but cannot fully close on a portable POSIX shell, the window
# between the final recheck and the write; see docs/AGENT-SKILLS.md.
assert_no_link() {
    current=$1
    while [ "$current" != "$base" ]; do
        [ ! -L "$current" ] || fail "Symlink destination: $current"
        current=${current%/*}
        [ -n "$current" ] || current=/
    done
}
# Preflight every destination (including receipt) before any write.
printf '%s\n' "$paths" '@OMJ_RECEIPT_NAME@' | while IFS= read -r path; do
    assert_no_link "$target/$path"
    [ ! -e "$target/$path" ] || [ -f "$target/$path" ] || fail "Not a file: $target/$path"
    [ "$path" = '@OMJ_RECEIPT_NAME@' ] || [ ! -e "$target/$path" ] || cmp -s "$source/$path" "$target/$path" || fail "Unowned or modified collision: $target/$path"
done
# Each write is: recheck the exact destination, create its content under an
# exclusive (O_CREAT|O_EXCL via shell noclobber) temp name in the same
# directory, then replace the destination with one atomic rename. rename(2)
# always replaces whatever directory entry is there; it never follows a
# symlink planted at the destination in the gap after the recheck.
write_atomic() {
    src=$1 dst=$2
    assert_no_link "$dst"
    tmp="$dst.$$.tmp"
    (set -C; cat "$src" > "$tmp") 2>/dev/null || fail "Temp write collision: $tmp"
    mv -f "$tmp" "$dst"
}
printf '%s\n' "$paths" | while IFS= read -r path; do
    assert_no_link "$target/${path%/*}"
    mkdir -p "$target/${path%/*}"
    write_atomic "$source/$path" "$target/$path"
done
verify "$target"
receipt_tmp="$target/@OMJ_RECEIPT_NAME@.$$.tmp"
(set -C; cat > "$receipt_tmp" <<'OMJ_RECEIPT'
@OMJ_RECEIPT@
OMJ_RECEIPT
) 2>/dev/null || fail "Temp write collision: $receipt_tmp"
assert_no_link "$target/@OMJ_RECEIPT_NAME@"
mv -f "$receipt_tmp" "$target/@OMJ_RECEIPT_NAME@"
printf 'Installed @OMJ_HOST@ skills in %s\n' "$target"
cat <<'OMJ_SKILLS'
@OMJ_SKILLS@
OMJ_SKILLS
''')


_PS1 = Template(r'''# Generated by omj docs agent-skills; edit the catalog/producer, not this file.
# Source inventory SHA256: @OMJ_DIGEST@
param([switch]$User)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
if ($args.Count) { throw 'Usage: install.ps1 [-User]' }
$base = (Get-Location).ProviderPath
if ($User) {
    $base = $env:USERPROFILE
    if (-not $base) { $base = $env:HOME }
    if (-not $base) { throw 'User profile is required for -User' }
    $target = Join-Path $base '@OMJ_USER_PATH@'
} else { $target = Join-Path $base '@OMJ_REPO_PATH@' }
$source = Join-Path (Split-Path -Parent $PSScriptRoot) '@OMJ_SOURCE_PS@'
$checksums = @'
@OMJ_CHECKSUMS@
'@
$entries = @($checksums.Split("`n") | ForEach-Object {
    $parts = $_.TrimEnd("`r") -split '  ', 2
    [PSCustomObject]@{ Path = $parts[1]; Hash = $parts[0] }
})
function Assert-NoLink([string]$Path, [string]$Boundary) {
    $current = $Path
    while ($current -and $current -ne $Boundary) {
        if (Test-Path -LiteralPath $current) {
            $item = Get-Item -Force -LiteralPath $current
            if ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) { throw "Reparse-point path: $current" }
        }
        $current = Split-Path -Parent $current
    }
}
Assert-NoLink $source (Split-Path -Parent $source)
$items = @(Get-ChildItem -Force -Recurse -LiteralPath $source)
foreach ($item in $items) {
    if ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) { throw "Reparse-point source: $($item.FullName)" }
}
$sourceFiles = @($items | Where-Object { -not $_.PSIsContainer })
if ($sourceFiles.Count -ne $entries.Count) { throw 'Source file inventory mismatch' }
function Assert-Digests([string]$Root) {
    foreach ($entry in $entries) {
        $path = Join-Path $Root $entry.Path
        if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { throw "Missing skill: $path" }
        if ((Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant() -cne $entry.Hash) { throw "Skill digest mismatch: $path" }
    }
}
Assert-Digests $source
foreach ($relative in (@($entries.Path) + '@OMJ_RECEIPT_NAME@')) {
    $path = Join-Path $target $relative
    Assert-NoLink $path $base
    if ((Test-Path -LiteralPath $path) -and -not (Test-Path -LiteralPath $path -PathType Leaf)) { throw "Not a file: $path" }
    if ((Test-Path -LiteralPath $path -PathType Leaf) -and $relative -ne '@OMJ_RECEIPT_NAME@') {
        $sourcePath = Join-Path $source $relative
        if ((Get-FileHash -LiteralPath $sourcePath -Algorithm SHA256).Hash.ToLowerInvariant() -cne (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant()) { throw "Unowned or modified collision: $path" }
    }
}
foreach ($entry in $entries) {
    $path = Join-Path $target $entry.Path
    [IO.Directory]::CreateDirectory((Split-Path -Parent $path)) | Out-Null
    # Recheck immediately before this exact write: a same-UID attacker who
    # plants a reparse point after the earlier preflight pass is still
    # caught right before the byte that path receives is written.
    Assert-NoLink $path $base
    [IO.File]::Copy((Join-Path $source $entry.Path), $path, $true)
}
Assert-Digests $target
$receipt = @'
@OMJ_RECEIPT@
'@
Assert-NoLink (Join-Path $target '@OMJ_RECEIPT_NAME@') $base
[IO.File]::WriteAllText((Join-Path $target '@OMJ_RECEIPT_NAME@'), $receipt.Replace("`r`n", "`n") + "`n", [Text.UTF8Encoding]::new($false))
Write-Output "Installed @OMJ_HOST@ skills in $target"
@'
@OMJ_SKILLS@
'@ -split "`n"
''')


def _render_template(template: Template, fields: dict[str, str]) -> str:
    """Replace only named generator fields; preserve shell/PowerShell dollars."""
    rendered = template.template
    for name, value in fields.items():
        rendered = rendered.replace(f"@OMJ_{name.upper()}@", value)
    return rendered


def host_adapter_files(files: dict[str, str], *, source: str = "agent-skills") -> dict[str, str]:
    """Return all 18 generated scripts/manifests from one source inventory."""
    result: dict[str, str] = {}
    receipt = json.dumps(agent_skills_manifest(files), indent=2, sort_keys=True)
    for adapter in HOST_ADAPTERS:
        manifest = host_adapter_manifest(adapter.host, files, source=source)
        fields = {
            "host": manifest["host"],
            "source_sh": shlex.quote(manifest["source_path"]),
            "source_ps": manifest["source_path"].replace("'", "''"),
            "receipt_name": MANIFEST_NAME,
            "receipt": receipt,
            "digest": manifest["source_digest"],
            "repo_path": manifest["targets"]["repo"],
            "user_path": manifest["targets"]["user"],
            "checksums": checksum_inventory(manifest["files"]).rstrip("\n"),
            "paths": "\n".join(manifest["files"]),
            "skills": "\n".join(manifest["skills"]),
        }
        result[f".{adapter.host}/install.sh"] = _render_template(_SH, fields)
        result[f".{adapter.host}/install.ps1"] = _render_template(_PS1, fields)
        result[f".{adapter.host}/manifest.json"] = json.dumps(manifest, indent=2, sort_keys=True) + "\n"
    return result
